action.command:
cd /workspace/GILT_Artifacts-main/study && cat > install_packages.R << 'EOF'
pkgs <- c(
  "lme4", "lmerTest", "MuMIn", "lattice", "car", "gridExtra", "plyr",
  "rsq", "parameters", "tidyverse", "dplyr", "tidyr", "reshape2"
)
missing <- setdiff(pkgs, rownames(installed.packages()))
if (length(missing) > 0) {
  install.packages(missing, repos = "https://cloud.r-project.org")
} else {
  message("All requested packages are already installed.")
}
EOF

